function filterButtons(){const side=FILTERS.map(([id,icon,key])=>`<button data-filter="${id}" class="${state.filter===id?'active':''}" aria-pressed="${state.filter===id}"><span aria-hidden="true">${icon}</span>${esc(emuT(key))}</button>`).join('');const sf=$('#sideFilters');if(sf)sf.innerHTML=side;$('#topFilters').innerHTML=FILTERS.map(([id,,key])=>`<button class="pill ${state.filter===id?'active':''}" data-filter="${id}" aria-pressed="${state.filter===id}">${esc(emuT(key))}</button>`).join('');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;filterButtons();render()})}
function filterButtons(){const side=FILTERS.map(([id,icon,key])=>`<button data-filter="${id}" class="${state.filter===id?'active':''}" aria-pressed="${state.filter===id}"><span aria-hidden="true">${icon}</span>${esc(emuT(key))}</button>`).join('');$('#sideFilters').innerHTML=side;$('#topFilters').innerHTML=FILTERS.map(([id,,key])=>`<button class="pill ${state.filter===id?'active':''}" data-filter="${id}" aria-pressed="${state.filter===id}">${esc(emuT(key))}</button>`).join('');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;filterButtons();render()})}
