try{parent.emuPaintHeaderIdentity&&parent.emuPaintHeaderIdentity()}catch(_){}})();
function openComposer(){openOverlay($('#composer'));window.EmuAnalytics?.track('post_create_start',{surface:'feed'})}function payload(){const lab=labPayload();return{title:$('#title').value.trim(),body:$('#body').value.trim(),tags:[state.composeTheme,$('#tags').value].filter(Boolean).join(','),imageUrl:state.imageUrl,...(lab?{lab}:{}),...(state.editingDraftId?{draftId:state.editingDraftId,draftSource:state.editingDraftSource||'emu'}:{})}}
/* 詳しく整理する（任意・11/7）：Knowledge Lab と同じ分類（/api/knowledge-lab/taxonomy）を、開いたときに読む。
   公開すると、親の画面が同じ投稿ID のまま Knowledge Lab の分類を付ける（新しい投稿は作らない）。AI の利用は、チェックしたときだけ。 */
const LAB_AXES={field:'分野',industry:'業種',occupation:'職業',experience:'経験の種類',purpose:'目的',kind:'知識の形式',genre:'ジャンル',difficulty:'難易度',audience:'対象者',period:'経験した時期'};state.labTerms=null;state.labPending={};state.labRendered=false;
function renderLabFacets(value){value=value||{};const terms=state.labTerms||[];$('#labFacets').innerHTML=Object.keys(LAB_AXES).map(axis=>{const t=terms.filter(x=>x.axis===axis&&((x.active!==false&&!x.mergedInto)||(value[axis]||[]).includes(x.id)));const n=(value[axis]||[]).length;return t.length?`<details class="lab-axis" data-lab-axis="${axis}"${axis==='field'||n?' open':''}><summary>${esc(LAB_AXES[axis])}（複数可）<small data-lab-count>${n?n+'件選択':''}</small></summary><div class="opts">${t.map(x=>`<label><input type="checkbox" value="${esc(x.id)}"${(value[axis]||[]).includes(x.id)?' checked':''}>${esc(x.label)}</label>`).join('')}</div></details>`:''}).join('');$('#labFacets').querySelectorAll('.lab-axis').forEach(d=>d.addEventListener('change',()=>{const k=d.querySelectorAll('input:checked').length;d.querySelector('[data-lab-count]').textContent=k?k+'件選択':''}));state.labRendered=true}
async function loadLabFacets(){if(state.labRendered)return;if(!state.labTerms){$('#labFacets').innerHTML='<p class="locked-note">分類を読み込んでいます…</p>';try{const r=await fetch('/api/knowledge-lab/taxonomy');const j=await r.json();if(!r.ok)throw new Error('taxonomy');state.labTerms=Array.isArray(j)?j:(j.items||[])}catch(e){$('#labFacets').innerHTML='<p class="locked-note">分類を読み込めませんでした。時期や学んだことは、このまま残せます。</p>';return}}if(!state.labRendered)renderLabFacets(state.labPending)}
function labFacetValue(){if(!state.labRendered)return {...(state.labPending||{})};const v={};document.querySelectorAll('#labFacets [data-lab-axis]').forEach(f=>{const ids=[...f.querySelectorAll('input:checked')].map(i=>i.value);if(ids.length)v[f.dataset.labAxis]=ids});return v}
function labPayload(){const v={facets:labFacetValue(),period:$('#labPeriod').value.trim(),happened:$('#labHappened').value.trim(),learned:$('#labLearned').value.trim(),advice:$('#labAdvice').value.trim(),sources:$('#labSources').value.trim(),verification:$('#labVerification').value,aiUseConsent:$('#labAIConsent').checked};return(Object.keys(v.facets).length||v.period||v.happened||v.learned||v.advice||v.sources||v.aiUseConsent||v.verification!=='self-reported')?v:null}
function fillLab(lab){lab=lab&&typeof lab==='object'?lab:{};$('#labPeriod').value=String(lab.period||'');$('#labHappened').value=String(lab.happened||'');$('#labLearned').value=String(lab.learned||'');$('#labAdvice').value=String(lab.advice||'');$('#labSources').value=String(lab.sources||'');$('#labVerification').value=['self-reported','tested-by-author','in-progress','needs-update'].includes(lab.verification)?lab.verification:'self-reported';$('#labAIConsent').checked=lab.aiUseConsent===true;state.labPending=lab.facets&&typeof lab.facets==='object'?lab.facets:{};state.labRendered=false;$('#labFacets').innerHTML='';if(labPayload()){$('#labMore').open=true;loadLabFacets()}}
$('#labMore').addEventListener('toggle',()=>{if($('#labMore').open){loadLabFacets();window.EmuAnalytics?.track('post_details',{stage:'open'})}});
function request(kind){if(!$('#composeForm').reportValidity())return;if(kind==='schedule'&&labPayload()&&!confirm('予約投稿には「詳しく整理する」の内容は付きません（公開されたあと、Knowledge Lab の「自分の経験知」から整理できます）。このまま予約しますか？'))return;const requestId=crypto.randomUUID?crypto.randomUUID():String(Date.now());state.pending={requestId,kind,updating:!!state.editingDraftId};setBusy(true);const type=kind==='publish'?'emu-knowledge-publish':kind==='draft'?'emu-knowledge-draft':'emu-knowledge-schedule',data=payload();if(kind==='schedule'){if(!$('#scheduledAt').value)return finish(false,emuT('k.toast.needSchedule'));data.scheduledAt=$('#scheduledAt').value}send({type,requestId,payload:data});notify(kind==='publish'?emuT('k.toast.publishing'):kind==='draft'?emuT('k.toast.saving'):emuT('k.toast.scheduling'))}
function finish(ok,error){setBusy(false);if(ok){const kind=state.pending?.kind,hadLab=!!labPayload();closeOverlay($('#composer'));resetComposer();afterSave(kind,hadLab);notify(state.pending?.kind==='draft'?emuT(state.pending.updating?'k.toast.draftUpdated':'k.toast.draftSaved'):state.pending?.kind==='schedule'?emuT('k.toast.scheduled'):emuT('k.toast.published'))}else notify(error||emuT('k.toast.failed'));state.pending=null}
/* 投稿のあとの案内（11/7）。公開したら：反応の見方・共有・次の投稿。分類を付けていなければ「詳しく整理する」も案内する。
   下書き・予約なら：まだ公開されていないことと、続きの場所。 */
function afterSave(kind,hadLab){const box=$('#afterSave');if(!box)return;const t={publish:['知識を公開しました。','読んだ人の Good・Change は、マイライブラリーの「自分の投稿」で見られます。'+(hadLab?'':'分野などを付けると Knowledge Lab で見つかりやすくなります（投稿画面の「詳しく整理する」、または Knowledge Lab の「自分の経験知」から）。')],draft:['下書きに保存しました（まだ公開されていません）。','マイライブラリーから、続きを書いて公開できます。'],schedule:['投稿を予約しました。','決めた日時に公開されます。それまでは公開されていません。']}[kind];if(!t){box.hidden=true;return}
